functions.getPrize:
{
   if(nowTask == undefined || nowTask.isComplete == false || nowTask.isDoing == false)
   {
      return false;
   }
   if(nowTask.name == "荣誉任务")
   {
      _global.msg.open("\r\r\r请到国王那里领取奖励。");
      return false;
   }
   var _loc6_;
   if(nowTask.name == "好友委托")
   {
      friend.isTask = false;
      _loc6_ = _parent.friend.getAllLevels();
      nowTask.prize[0] = {type:"魔石",val:_loc6_ * 10 + 100};
      switch(Math.floor(_loc6_ / 7))
      {
         case 0:
            nowTask.prize[1] = {type:"奇异兽"};
            break;
         case 1:
            nowTask.prize[1] = {type:"6星奇异兽"};
            break;
         case 2:
            nowTask.prize[1] = {type:"8星奇异兽"};
            break;
         case 3:
            nowTask.prize[1] = {type:"12星奇异兽"};
            break;
         case 4:
            nowTask.prize[1] = {type:"15星奇异兽"};
            break;
         case 5:
            nowTask.prize[1] = {type:"19星奇异兽"};
            break;
         case 6:
         default:
            nowTask.prize[1] = {type:"23星奇异兽"};
      }
      _global.sysMsg.addMsg("获得 " + nowTask.prize[1].type);
   }
   var _loc5_;
   _loc5_ = nowTask.prize.length;
   var _loc4_;
   while(_loc5_)
   {
      switch(nowTask.prize[_loc5_ - 1].type)
      {
         case "魔石":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "魔石");
            this._parent.map.role.xxx_ms += nowTask.prize[_loc5_ - 1].val;
            break;
         case "资源":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "资源");
            this._parent.map.role.xxx_res += nowTask.prize[_loc5_ - 1].val;
            break;
         case "军功":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "军功");
            this._parent.map.role.militaryExploitUp(nowTask.prize[_loc5_ - 1].val);
            break;
         case "功勋":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "功勋");
            this._parent.map.role.exploitUp(nowTask.prize[_loc5_ - 1].val);
            break;
         case "声望":
            this._parent.map.role.creditUp(nowTask.prize[_loc5_ - 1].val);
            break;
         case "出征3个幻兽":
            _global.sysMsg.addMsg("!!! " + role.myName + "竟然掌握同时出征3个幻兽的能力，恭喜");
            this._parent.huanShou.maxBattleNum = 3;
            break;
         case "接荣誉任务":
            _global.msg.open("\r\r\r接受国王委托任务 荣誉任务",this.setHonorTask,true);
            break;
         default:
            if(nowTask.prize[_loc5_ - 1].type == "武器" || nowTask.prize[_loc5_ - 1].type == "衣服" || nowTask.prize[_loc5_ - 1].type == "头盔" || nowTask.prize[_loc5_ - 1].type == "鞋" || nowTask.prize[_loc5_ - 1].type == "幸运符" || nowTask.prize[_loc5_ - 1].type == "庇护铃铛" || nowTask.prize[_loc5_ - 1].type == "翡翠铃铛" || nowTask.prize[_loc5_ - 1].type == "凤翼铃铛")
            {
               _parent.upDataWeapon(nowTask.prize[_loc5_ - 1]);
               _parent.backPack.setThing(nowTask.prize[_loc5_ - 1]);
               break;
            }
            if(nowTask.prize[_loc5_ - 1].number > 0)
            {
               _loc4_ = 0;
               while(_loc4_ < nowTask.prize[_loc5_ - 1].number)
               {
                  _parent.createThing(nowTask.prize[_loc5_ - 1]);
                  _loc4_ = _loc4_ + 1;
               }
               break;
            }
            _parent.createThing(nowTask.prize[_loc5_ - 1]);
      }
      _loc5_ = _loc5_ - 1;
   }
   if(nowTask.type == "日常任务")
   {
      _loc5_ = 0;
      while(_loc5_ < nowTask.need.length)
      {
         nowTask.need[_loc5_].number = 0;
         _loc5_ = _loc5_ + 1;
      }
      nowTask.isComplete = false;
   }
   nowTask.isDoing = false;
   nowTask = undefined;
   showTask(this.nowTaskType);
}

